"""Build an evidence-linked report and task-indexed comparison bundles from actual campaign artifacts."""
import pathlib,json,csv,statistics,sys,hashlib,shutil
ROOT=pathlib.Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'runtime'))
import run_campaign_20261111 as C
RUN=C.RUN;OUT=C.BMD

def j(p):return json.loads(pathlib.Path(p).read_text())
def fmt(x):return 'NA' if x is None else f'{x:.4f}'
C.dump(OUT/'boltzmann_attempt.json',{'job_name':'rna_siRNA_gen','doc_id':'6af45c45b7e34e64c3637a3a','experiment_name':'siRNA Generation - 20261111-121459Z - 7cdd23','submission':'accepted','terminal_status':'failed','status_message':'job failed','service_diagnostic':'RuntimeError: Inference failed: STDOUT: None STDERR: None','job_terminal_confirmed':True,'candidate_artifact_returned':False,'resubmitted':False,'fallback':'User explicitly approved local backend execution after this observed terminal failure.','warning_approved':'FASTA record syntax checked; biological sequence suitability is not established by this check.','TTR_input_sha256':C.sha(ROOT/'results/003_genetic-disease-total-lowering'/RUN/'00_inputs/transcript.fa')})
# Preserve native outputs, remove only newly created disposable runtime copies/symlinks.
